WHO = {'column': [('dureben', 268981), ('brifeefli', 268981), ('psilogepy', 0), ('uneyeelldum', 0), ('quhlyelfldum', 0), ('brifeeefli', 269045), ('aprilclysen', 269045), ('mueflhili', 269233)], 'tree': [('aprilfools', 268981), ('brifeeefli', 0), ('mufoeova', 269682), ('mueflfelysen', 270189), ('brifecuya', 270189), ('yaflut', 271139), ('brifeeben', 0), ('brifeeefli', 0)], 'manor': [('thilfldum', 0), ('mulcefli', 270631), ('mufoeova', 271651), ('senthili', 0), ('einsof', 277307), ('mulcefli', 278576), ('aprilfools', 279910), ('mufoeova', 0)], 'bridge': [('alphaffelsof', 0), ('alphafoldmicro', 270189), ('alphafolsof', 0), ('alphafoldmicro', 275143), ('alphafolsof', 278006), ('alphafoldmicro', 281566)], 'tower': [('psilogepy', 270887), ('alphafolsof', 271331), ('dureben', 0), ('psilogepy', 0), ('qum', 272538), ('eindmelldum', 272538), ('mulceflhili', 277243), ('psilogepy', 0)], 'temple': [('psilogepy', 272289), ('mueflhili', 272538), ('yaflut', 0), ('psilogepy', 278198), ('alphaffelsof', 278704), ('alphafolsof', 279659), ('psilogepy', 283536)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW334(OracleReleaseRuntimeW472):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
